J='stroke-linejoin="round" stroke-linecap="round"'
def rc(x,y,w,h,f,sw=5,rx=0):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}"'+(f' rx="{rx}"' if rx else '')+f' fill="{f}" stroke="{N}" stroke-width="{sw}" {J}/>'
def pg(p,f,sw=5):
    return f'<polygon points="{" ".join(f"{a},{b}" for a,b in p)}" fill="{f}" stroke="{N}" stroke-width="{sw}" {J}/>'
def ci(cx,cy,r,f,sw=5):
    return f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="{f}" stroke="{N}" stroke-width="{sw}"/>'
def ln(p,c=N,sw=5):
    return f'<polyline points="{" ".join(f"{a},{b}" for a,b in p)}" fill="none" stroke="{c}" stroke-width="{sw}" {J}/>'
def pth(d,f,sw=5):
    return f'<path d="{d}" fill="{f}" stroke="{N}" stroke-width="{sw}" {J}/>'
def heap(cx,base,hw,h,f):
    return pg([(cx-hw,base),(cx-hw*.45,base-h*.7),(cx,base-h),(cx+hw*.45,base-h*.75),(cx+hw,base)],f)
def frame(cx,base,top,f,wheel=True):
    s=rc(0,0,0,0,f,0)[:0]
    s+=pg([(cx-26,base),(cx-7,top),(cx+7,top),(cx+26,base)],f)
    s+=ln([(cx-20,base-(base-top)*.3),(cx+20,base-(base-top)*.62)],N,4)+ln([(cx+20,base-(base-top)*.3),(cx-20,base-(base-top)*.62)],N,4)
    if wheel: s+=ci(cx,top,12,LT)+ci(cx,top,4,G,3)
    return s
def door(x,y,w,h,f=B):
    return rc(x,y,w,h,f)
def win(x,y,w,h,f=LT):
    return rc(x,y,w,h,f,4)
def stripes(x,y,w,h,n,f=YL):
    s=rc(x,y,w,h,f,4)
    sw=w/n
    for i in range(0,n,2):
        a=x+i*sw
        s+=f'<polygon points="{a+2},{y+h-2} {a+sw*.5+2},{y+h-2} {a+sw*.5+h*.5},{y+2} {a+h*.5},{y+2}" fill="{BK}"/>'
    return s+rc(x,y,w,h,'none',4)
def tank(x,y,w,h,f,band=None):
    s=rc(x,y,w,h,f,5,min(w//2,12))
    if band: s+=rc(x,y+h*.3,w,6,band,3)
    return s
def conv(x1,y1,x2,y2,f=SL):
    dx,dy=x2-x1,y2-y1;l=math.hypot(dx,dy);nx,ny=-dy/l*6,dx/l*6
    return pg([(x1+nx,y1+ny),(x2+nx,y2+ny),(x2-nx,y2-ny),(x1-nx,y1-ny)],f,4)
def gable(x1,x2,yb,yt,f):
    return pg([(x1,yb),((x1+x2)/2,yt),(x2,yb)],f)
